			const coeff = 2 * Math.cos(omega);
			let sPrev = 0;
			let sPrev2 = 0;
			for (let i = 0; i < n; i++) {
				const s = segment[i] + coeff * sPrev - sPrev2;
				sPrev2 = sPrev;
				sPrev = s;
			}
			const power = sPrev2 * sPrev2 + sPrev * sPrev - coeff * sPrev * sPrev2;
			total += Math.max(0, power) / (n * n);
