		const firstHalfRms = rmsFrames.slice(0, mid).reduce((a, b) => a + b, 0) / mid;
		const secondHalfRms = rmsFrames.slice(mid).reduce((a, b) => a + b, 0) / Math.max(1, rmsFrames.length - mid);
