			let dot = 0;
			let magA = 0;
			let magB = 0;
			for (let i = 0; i < len; i++) {
				const rawA = sigA[start + i];
				const rawB = sigB[start + i + lag];
				const a = Number.isFinite(rawA) ? rawA : 0;
				const b = Number.isFinite(rawB) ? rawB : 0;
				dot += a * b;
				magA += a * a;
				magB += b * b;
			}
			const corr = Math.abs(dot) / (Math.sqrt(magA * magB) + 1e-12);
			if (corr > maxCorr) maxCorr = corr;
