	const trainSpeakers = Array.from(new Set(splitSamples.filter((s) => s.assigned_split === "train").map((s) => s.speaker_id)));
	const validationSpeakers = Array.from(new Set(splitSamples.filter((s) => s.assigned_split === "validation").map((s) => s.speaker_id)));
	const testSpeakers = Array.from(new Set(splitSamples.filter((s) => s.assigned_split === "test").map((s) => s.speaker_id)));
	const trainSet = new Set(trainSpeakers);
	const valSet = new Set(validationSpeakers);
	let speakerLeakageCount = 0;
	for (const tSpk of testSpeakers) if (trainSet.has(tSpk) || valSet.has(tSpk)) speakerLeakageCount++;
	for (const vSpk of validationSpeakers) if (trainSet.has(vSpk)) speakerLeakageCount++;
	const testManifestString = splitSamples.filter((s) => s.assigned_split === "test").map((s) => `${s.sample_id}:${s.audio_hash}`).sort().join("|");
