	if (!input.allLicensesVerifiedForTraining) blockers.push("LICENSE_BLOCKER: Not all training data sources have verified legal training permissions.");
	if (!input.speakerDisjointHoldoutAvailable) blockers.push("HOLDOUT_BLOCKER: Speaker-disjoint protected evaluation holdout is missing.");
