	let trackBPrototypeDecision = "GO_SMALL_ENGINEERING_PROTOTYPE_ONLY";
	let trackBProductionFromScratchDecision = "NO_GO_INSUFFICIENT_DATA_OR_COMPUTE";
	if (!legalAndHoldoutOk) trackBPrototypeDecision = "NO_GO_BLOCKED";
