// src/components/WorkflowStageBar.tsx
function formatMb(bytes) {
	return `${(bytes / 1048576).toFixed(1)} MB`;
}
function asrLabel(state, locale, companionHealth) {
	const isFa = locale === "fa";
	switch (state) {
		case "MODEL_NOT_INSTALLED": return isFa ? "مدل محلی نصب نشده" : "Local ASR Not Installed";
		case "MODEL_AVAILABLE": return isFa ? "مدل محلی ذخیره و تأیید شد (در انتظار اجرا)" : "Local Model Verified (OPFS)";
		case "MODEL_INTEGRITY_FAILURE": return isFa ? "خطای اصالت مدل" : "Model Integrity Failure";
		case "RUNTIME_UNAVAILABLE": return isFa ? "موتور WASM/ORT ناموجود" : "Runtime Unavailable";
		case "MODEL_LOADING": return isFa ? "بارگذاری مدل محلی..." : "Loading Local Model...";
		case "MODEL_READY":
			if (companionHealth?.runtime?.available) return isFa ? "موتور بومی شهاب/شناوا آماده" : "Native Engine Ready (Shenava-Rizeh)";
			return isFa ? "مدل محلی آماده" : "Local Model Ready";
		case "INFERENCE_RUNNING": return isFa ? "در حال رونویسی محلی..." : "Running Local ASR...";
		case "INFERENCE_FAILED": return isFa ? "خطای رونویسی محلی" : "Local ASR Failed";
		case "NO_SPEECH_DETECTED": return isFa ? "گفتاری شناسایی نشد" : "No Speech Detected";
		case "TRANSCRIPTION_COMPLETED": return isFa ? "رونویسی تکمیل شد" : "Transcription Completed";
		case "TRANSCRIPTION_CANCELLED": return isFa ? "رونویسی لغو شد" : "Transcription Cancelled";
	}
}
