function formatClockTime(timestampMs, locale) {
	if (timestampMs === null || !Number.isFinite(timestampMs)) return "—";
	const d = new Date(timestampMs);
	const raw = `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}:${String(d.getSeconds()).padStart(2, "0")}`;
	return locale === "fa" ? raw : raw;
}
