	writeSpeechEnvelope(pcm, sampleRate, 1.3, 1.85, 184, .43);
	writeSpeechEnvelope(pcm, sampleRate, 1.92, 2.52, 172, .35, true);
	writeSpeechEnvelope(pcm, sampleRate, 2.62, 3.15, 188, .41);
	writeSpeechEnvelope(pcm, sampleRate, 3.22, 3.74, 185, .4);
	writeSpeechEnvelope(pcm, sampleRate, 4.85, 5.55, 189, .42);
	writeSpeechEnvelope(pcm, sampleRate, 5.62, 6.02, 184, .38);
	writeSpeechEnvelope(pcm, sampleRate, 6.08, 6.55, 186, .4);
	writeSpeechEnvelope(pcm, sampleRate, 6.62, 7.18, 180, .39);
