		const visibleSeconds = (viewportRange.end - viewportRange.start) / FLICKS_PER_SECOND;
		const idealSamplesPerPixel = Math.max(0, visibleSeconds * sampleRate) / Math.max(1, canvasWidthPx);
		const sorted = [...lods].sort((a, b) => a.samplesPerPeak - b.samplesPerPeak);
		let chosen = sorted[0];
		for (const lod of sorted) if (lod.samplesPerPeak <= idealSamplesPerPixel) chosen = lod;
		else break;
